exec('iwinfo ' + intf + ' scan', function (error, stdout, stderr) {
        if (error) {
            stderr = stderr.trim();
            return callback(new Error(stderr));
        }

        var info = stdout,
            parsed = [];

        info = info.replace(/\n/g, ' ');
        info = info.replace(/"/g, '');
        info = info.split(' ');
        info.forEach(function (char, i) {
            if (char === 'ESSID' && info[i+1] === '')
                info[i+1] = 'unknown';
            else if (char !== '')
                parsed.push(char);
        });

        parsed = parse(parsed);
        callback(null, parsed);
    })
